auditd.source:
. |= parse_regex!(.message, r'^type=(?<type>\S+) msg=audit\((?<epoch>\d+\.\d{3}):(?<serial>\d+)\): (?<rest>.*)$')
pairs = parse_regex_all!(.rest, r'(\S+?)=("(?:[^"\\]|\\.)*"|\S*)', numeric_groups: true)
for_each(array!(pairs)) -> |_index, pair| {
  key = string!(pair."1")
  raw_value = string!(pair."2")
  value = if starts_with(raw_value, "\"") {
    replace(slice!(raw_value, 1, -1), "\\\"", "\"")
  } else {
    raw_value
  }
  . = set!(., [key], value)
}
del(.rest)
del(.message)
.syscall = to_int!(.syscall)
.exit = to_int!(.exit)
.uid = to_int!(.uid)
.gid = to_int!(.gid)
